  ('a6830d83-4a67-5193-b12d-17ab4b8a3ce8', '445534c6-3df0-5148-a006-78993ad8b6cd', 'Army', 'enlisted', '42A', 'Human Resources Specialist', 'assignments', 'E-7', null, 'Broadening assignments', 'Chapter 4. Military occupational specialty 42A human resources specialist', 'Drill Sergeant; Recruiter; Equal Opportunity Advisor; Assistant Inspector General; Army/Joint/NATO Staff; Sexual Assault Response Coordinator; Observer/Controller; Training with Industry; Defense Attaché; Defense Courier; Senior AIT Instructor; Senior Noncommissioned Officer Academy Small Group Leader; Writer/Developer; IPPS-A Field Integrator; Executive Admin NCO.', 'c551733dff12e2169b7853d3cb3b20f5bf6c5a580db79125f976c0b412cdb02d', 10, 10, null, 33),
  ('554fa309-b17f-56fe-98e2-2723785f3b11', '445534c6-3df0-5148-a006-78993ad8b6cd', 'Army', 'enlisted', '42A', 'Human Resources Specialist', 'training', 'E-7', null, 'Institutional training', 'Chapter 4. Military occupational specialty 42A human resources specialist', '(1) Professional Military Education: Senior Leader Course (SLC). Promotion to MSG requires SLC graduation. Consider NCOs ahead of their peers and best qualified for promotion if they achieve distinguished recognition such as Distinguished Honor Graduate, Distinguished Leadership Award, and Commands List.
